"use client"

import * as React from "react"
import { Download, Maximize, Minus, Plus, RotateCw } from "lucide-react"

import { cn } from "@/lib/utils"
import type { ViewerDownloadAction } from "@/lib/viewer-download-actions"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"
import {
  ViewerDownloadControl,
  type ViewerDownloadErrorHandler,
} from "@/components/ui/viewer-download"

export type ViewerControlPosition =
  | {
      kind: "page" | "slide" | "frame"
      current: number
      total?: number
    }
  | {
      label: React.ReactNode
    }

export type ViewerZoomControl = {
  scale: number | null
  onZoomOut: () => void
  onZoomIn: () => void
  onFit?: () => void
  onReset?: () => void
  fitLabel?: string
  isDisabled?: boolean
}

export type ViewerRotateControl = {
  onRotate: () => void
  isDisabled?: boolean
}

export type ViewerControlsState = {
  title?: React.ReactNode
  subtitle?: React.ReactNode
  position?: ViewerControlPosition | null
  zoom?: ViewerZoomControl | null
  rotate?: ViewerRotateControl | null
  downloads?: ViewerDownloadAction[]
  loading?: boolean
  extra?: React.ReactNode
}

type ViewerControlsRegistration = (state: ViewerControlsState | null) => void
type ViewerControlsRegistrar = (
  registrationId: symbol,
  state: ViewerControlsState | null
) => void

const ViewerControlsRegistrationContext =
  React.createContext<ViewerControlsRegistrar | null>(null)

export function ViewerControlsRegistrationProvider({
  children,
  onControlsChange,
}: {
  children: React.ReactNode
  onControlsChange: ViewerControlsRegistration
}) {
  const activeRegistrationRef = React.useRef<symbol | null>(null)
  const registerControls = React.useCallback<ViewerControlsRegistrar>(
    (registrationId, state) => {
      if (state) {
        activeRegistrationRef.current = registrationId
        onControlsChange(state)
        return
      }

      if (activeRegistrationRef.current !== registrationId) return
      activeRegistrationRef.current = null
      onControlsChange(null)
    },
    [onControlsChange]
  )

  return (
    <ViewerControlsRegistrationContext.Provider value={registerControls}>
      {children}
    </ViewerControlsRegistrationContext.Provider>
  )
}

export function useViewerControlsRegistration(): ViewerControlsRegistration | null {
  const registerControls = React.useContext(ViewerControlsRegistrationContext)
  const registrationId = React.useMemo(
    () => Symbol("viewer-controls-registration"),
    []
  )

  return React.useMemo(() => {
    if (!registerControls) return null
    return (state) => registerControls(registrationId, state)
  }, [registerControls, registrationId])
}

export type ViewerControlsProps = Omit<React.ComponentProps<"div">, "title"> & {
  title?: React.ReactNode
  subtitle?: React.ReactNode
  position?: ViewerControlPosition | null
  zoom?: ViewerZoomControl | null
  rotate?: ViewerRotateControl | null
  downloads?: ViewerDownloadAction[]
  onDownloadError?: ViewerDownloadErrorHandler
  loading?: boolean
  size?: "default" | "sm"
  extra?: React.ReactNode
}

export type ViewerControlsSkeletonProps = Omit<
  React.ComponentProps<"div">,
  "title"
> & {
  title?: boolean
  subtitle?: boolean
  position?: boolean
  zoom?: boolean
  rotate?: boolean
  download?: boolean
  extra?: React.ReactNode
}

export const VIEWER_CONTROLS_HEIGHT_PX = 40

export function ViewerControls({
  className,
  title,
  subtitle,
  position,
  zoom,
  rotate,
  downloads,
  onDownloadError,
  loading = false,
  size = "default",
  extra,
  ...props
}: ViewerControlsProps) {
  const hasDownloads = Boolean(downloads?.length)
  const hasControls = Boolean(zoom || rotate || hasDownloads || extra)
  const hasPlainTitle = typeof title === "string" || typeof title === "number"
  const hasMetadataGroup = loading || title != null || subtitle != null

  return (
    <div
      data-slot="viewer-controls"
      className={cn(
        "flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2",
        size === "sm" && "h-9 px-2",
        className
      )}
      {...props}
    >
      {hasMetadataGroup ? (
        <div className="flex min-w-0 flex-1 items-center gap-1.5 overflow-hidden">
          {loading ? (
            <span
              aria-hidden
              className="size-2 flex-shrink-0 animate-pulse rounded-full bg-primary"
            />
          ) : null}
          {title != null ? (
            <div
              className={cn(
                "min-w-0 px-1",
                hasPlainTitle && "truncate text-xs font-medium"
              )}
            >
              {title}
            </div>
          ) : null}
          {subtitle != null ? (
            <span className="hidden min-w-0 truncate px-1 text-xs text-muted-foreground tabular-nums sm:inline">
              {subtitle}
            </span>
          ) : null}
          {position ? (
            <span className="flex-shrink-0 px-1 text-xs text-muted-foreground tabular-nums">
              {formatViewerControlPosition(position)}
            </span>
          ) : null}
        </div>
      ) : position ? (
        <span className="flex-shrink-0 px-1 text-xs text-muted-foreground tabular-nums">
          {formatViewerControlPosition(position)}
        </span>
      ) : (
        <div className="min-w-0 flex-1" />
      )}

      {hasControls ? (
        <div className="ml-auto flex flex-shrink-0 items-center gap-1">
          {zoom ? <ViewerZoomControls zoom={zoom} /> : null}
          {zoom && rotate ? <ViewerControlSeparator /> : null}
          {rotate ? <ViewerRotateControlButton rotate={rotate} /> : null}
          {(zoom || rotate) && hasDownloads ? <ViewerControlSeparator /> : null}
          {hasDownloads ? (
            <ViewerDownloadControl
              actions={downloads ?? []}
              onError={onDownloadError}
            />
          ) : null}
          {(zoom || rotate || hasDownloads) && extra ? (
            <ViewerControlSeparator />
          ) : null}
          {extra}
        </div>
      ) : null}
    </div>
  )
}

export function ViewerControlsSkeleton({
  className,
  title = false,
  subtitle = false,
  position = false,
  zoom = false,
  rotate = false,
  download = false,
  extra,
  ...props
}: ViewerControlsSkeletonProps) {
  const hasControls = zoom || rotate || download || Boolean(extra)

  return (
    <div
      data-slot="viewer-controls-skeleton"
      className={cn(
        "flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2",
        className
      )}
      {...props}
    >
      <div className="flex min-w-0 flex-1 items-center gap-1.5 overflow-hidden">
        {title ? (
          <span className="min-w-0 truncate px-1">
            <Skeleton className="inline-block h-3 w-24 align-middle" />
          </span>
        ) : null}
        {subtitle ? (
          <span className="hidden min-w-0 truncate px-1 sm:inline">
            <Skeleton className="inline-block h-3 w-16 align-middle" />
          </span>
        ) : null}
        {position ? (
          <span className="flex-shrink-0 px-1">
            <Skeleton className="inline-block h-3 w-12 align-middle" />
          </span>
        ) : null}
      </div>

      {hasControls ? (
        <div className="ml-auto flex flex-shrink-0 items-center gap-1">
          {zoom ? (
            <>
              <ViewerControlButton
                disabled
                aria-hidden
                tabIndex={-1}
                label="Zoom out"
              >
                <Minus />
              </ViewerControlButton>
              <span className="w-12 text-center">
                <Skeleton className="inline-block h-3 w-8 align-middle" />
              </span>
              <ViewerControlButton
                disabled
                aria-hidden
                tabIndex={-1}
                label="Zoom in"
              >
                <Plus />
              </ViewerControlButton>
              <ViewerControlButton
                disabled
                aria-hidden
                tabIndex={-1}
                label="Fit width"
              >
                <Maximize />
              </ViewerControlButton>
            </>
          ) : null}
          {zoom && rotate ? <ViewerControlSeparator /> : null}
          {rotate ? (
            <ViewerControlButton
              disabled
              aria-hidden
              tabIndex={-1}
              label="Rotate"
            >
              <RotateCw />
            </ViewerControlButton>
          ) : null}
          {(zoom || rotate) && download ? <ViewerControlSeparator /> : null}
          {download ? (
            <ViewerControlButton
              disabled
              aria-hidden
              tabIndex={-1}
              label="Download"
            >
              <Download />
            </ViewerControlButton>
          ) : null}
          {(zoom || rotate || download) && extra ? (
            <ViewerControlSeparator />
          ) : null}
          {extra}
        </div>
      ) : null}
    </div>
  )
}

export function ViewerControlButton({
  label,
  children,
  className,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="iconSm"
      className={cn("size-7", className)}
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

export function formatViewerControlPosition(position: ViewerControlPosition) {
  if ("label" in position) return position.label

  const label =
    position.kind === "page"
      ? "Page"
      : position.kind === "slide"
        ? "Slide"
        : "Frame"
  const current =
    position.total == null
      ? position.current
      : Math.min(position.current, position.total)

  return position.total == null
    ? `${label} ${current}`
    : `${label} ${current} of ${position.total}`
}

function ViewerZoomControls({ zoom }: { zoom: ViewerZoomControl }) {
  const fitLabel = zoom.fitLabel ?? "Fit width"

  return (
    <>
      <ViewerControlButton
        label="Zoom out"
        onClick={zoom.onZoomOut}
        disabled={zoom.isDisabled}
      >
        <Minus />
      </ViewerControlButton>
      {zoom.onReset ? (
        <button
          type="button"
          className="w-12 text-center text-xs text-muted-foreground tabular-nums hover:text-foreground disabled:pointer-events-none disabled:opacity-64"
          title="Reset zoom"
          onClick={zoom.onReset}
          disabled={zoom.isDisabled}
        >
          {zoom.scale == null ? "Fit" : `${Math.round(zoom.scale * 100)}%`}
        </button>
      ) : (
        <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
          {zoom.scale == null ? "Fit" : `${Math.round(zoom.scale * 100)}%`}
        </span>
      )}
      <ViewerControlButton
        label="Zoom in"
        onClick={zoom.onZoomIn}
        disabled={zoom.isDisabled}
      >
        <Plus />
      </ViewerControlButton>
      {zoom.onFit ? (
        <ViewerControlButton
          label={fitLabel}
          onClick={zoom.onFit}
          disabled={zoom.isDisabled}
        >
          <Maximize />
        </ViewerControlButton>
      ) : null}
    </>
  )
}

function ViewerRotateControlButton({
  rotate,
}: {
  rotate: ViewerRotateControl
}) {
  return (
    <ViewerControlButton
      label="Rotate"
      onClick={rotate.onRotate}
      disabled={rotate.isDisabled}
    >
      <RotateCw />
    </ViewerControlButton>
  )
}

function ViewerControlSeparator() {
  return <Separator orientation="vertical" className="mx-1 h-4" />
}

"use client"

import * as React from "react"
import { Download } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download-actions"

import { Spinner } from "@/components/ui/spinner"

import { Button, buttonVariants } from "./button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "./dropdown-menu"

export interface TriggerViewerDownloadOptions {
  signal?: AbortSignal
}

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: TriggerViewerDownloadOptions
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    })
  }

  let payload: ViewerDownloadPayload
  try {
    payload = await action.getPayload(options)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      })
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    })
  }

  if (payload.kind === "none") return
  if (payload.kind === "href") {
    try {
      clickDownload(payload.href, action.fileName)
    } catch (error) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "unsupported",
        message: "Could not start this download.",
        cause: error,
      })
    }
    return
  }

  try {
    const blob =
      payload.kind === "blob"
        ? payload.blob
        : new Blob([payload.text], {
            type: payload.mimeType ?? "text/plain;charset=utf-8",
          })
    const url = URL.createObjectURL(blob)
    try {
      clickDownload(url, action.fileName)
    } finally {
      URL.revokeObjectURL(url)
    }
  } catch (error) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "unsupported",
      message: "Could not start this download.",
      cause: error,
    })
  }
}

export type ViewerDownloadErrorHandler = (
  error: ViewerDownloadError,
  action: ViewerDownloadAction
) => void

export interface ViewerDownloadTrigger {
  pendingActionId: string | null
  triggerDownload: (action: ViewerDownloadAction) => void
}

export interface ViewerDownloadTriggerOptions {
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler
  resetKey?: unknown
}

export interface ViewerDownloadControlProps {
  actions: Array<ViewerDownloadAction | null | undefined>
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler
}

export interface ViewerDownloadButtonProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  action: ViewerDownloadAction | null
}

export interface ViewerDownloadMenuProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  actions: ViewerDownloadAction[]
}

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null
): string | null {
  const shouldCreateHref = action?.origin !== "derived"
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null
}

export function useViewerDownloadTrigger({
  onError,
  resetKey = "",
}: ViewerDownloadTriggerOptions = {}): ViewerDownloadTrigger {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null
  )
  const abortControllerRef = React.useRef<AbortController | null>(null)

  React.useEffect(() => {
    return () => {
      abortControllerRef.current?.abort()
      abortControllerRef.current = null
    }
  }, [resetKey])

  const triggerDownload = React.useCallback(
    (action: ViewerDownloadAction) => {
      abortControllerRef.current?.abort()
      const abortController = new AbortController()
      abortControllerRef.current = abortController
      setPendingActionId(action.id)
      void triggerViewerDownload(action, { signal: abortController.signal })
        .catch((error) => {
          reportDownloadError(error, action, onError)
        })
        .finally(() => {
          if (abortControllerRef.current === abortController) {
            abortControllerRef.current = null
            setPendingActionId(null)
          }
        })
    },
    [onError]
  )

  return { pendingActionId, triggerDownload }
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadControlProps) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action)
  )

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
        onError={onError}
      />
    )
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
      onError={onError}
    />
  )
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadButtonProps) {
  const href = useViewerDownloadHref(action)
  const label = action?.label ?? "Download"
  const disabled = !action || action.isDisabled
  const hasDownloadHref = Boolean(href)
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: action,
  })
  const isPending = Boolean(action && pendingActionId === action.id)

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return
    triggerDownload(action)
  }, [action, hasDownloadHref, triggerDownload])

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    )
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled || isPending}
      onClick={handleClick}
    >
      {isPending ? (
        <Spinner className="size-4 animate-spin" />
      ) : (
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      )}
      {showLabel ? label : null}
    </Button>
  )
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadMenuProps) {
  const actionSetKey = actions.map((action) => action.id).join("\u0000")
  const label = "Download"
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: actionSetKey,
  })

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant={variant}
          size={size}
          className={className}
          aria-label={label}
          title={label}
          disabled={pendingActionId != null}
        >
          {pendingActionId != null ? (
            <Spinner className="size-4 animate-spin" />
          ) : (
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
          )}
          {showLabel ? label : null}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => triggerDownload(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a")
  anchor.href = href
  anchor.download = fileName
  anchor.rel = "noreferrer"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null
  const payload = action.getPayload()
  return payload instanceof Promise ? null : payload
}

function reportDownloadError(
  error: unknown,
  action: ViewerDownloadAction,
  onError: ViewerDownloadErrorHandler | undefined
) {
  if (!(error instanceof ViewerDownloadError)) return
  if (error.kind === "aborted") return
  onError?.(error, action)
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

export type ViewerDownloadOrigin = "original" | "derived"

export type ViewerDownloadPayload =
  | { kind: "href"; href: string }
  | { kind: "blob"; blob: Blob }
  | { kind: "text"; text: string; mimeType?: string }
  | { kind: "none" }

export interface ViewerDownloadAction {
  id: string
  label: string
  fileName: string
  origin: ViewerDownloadOrigin
  isDisabled?: boolean
  getPayload: (options?: {
    signal?: AbortSignal
  }) => ViewerDownloadPayload | Promise<ViewerDownloadPayload>
}

export type ViewerDownloadErrorKind =
  | "disabled"
  | "aborted"
  | "payload_failed"
  | "unsupported"

export class ViewerDownloadError extends Error {
  readonly kind: ViewerDownloadErrorKind
  readonly actionId: string
  override readonly cause?: unknown

  constructor({
    actionId,
    kind,
    message,
    cause,
  }: {
    actionId: string
    kind: ViewerDownloadErrorKind
    message: string
    cause?: unknown
  }) {
    super(message)
    this.name = "ViewerDownloadError"
    this.actionId = actionId
    this.kind = kind
    this.cause = cause
  }
}

export function createHrefDownloadAction({
  id,
  label = "Download",
  href,
  fileName,
  origin = "original",
}: {
  id: string
  label?: string
  href: string
  fileName: string
  origin?: ViewerDownloadOrigin
}): ViewerDownloadAction {
  return {
    id,
    label,
    fileName,
    origin,
    getPayload: () => ({ kind: "href", href }),
  }
}

export function createBlobDownloadAction({
  id,
  label = "Download",
  blob,
  fileName,
  origin = "original",
}: {
  id: string
  label?: string
  blob: Blob
  fileName: string
  origin?: ViewerDownloadOrigin
}): ViewerDownloadAction {
  return {
    id,
    label,
    fileName,
    origin,
    getPayload: () => ({ kind: "blob", blob }),
  }
}

export function createTextDownloadAction({
  id,
  label = "Download",
  text,
  fileName,
  mimeType,
  origin = "original",
}: {
  id: string
  label?: string
  text: string
  fileName: string
  mimeType?: string
  origin?: ViewerDownloadOrigin
}): ViewerDownloadAction {
  return {
    id,
    label,
    fileName,
    origin,
    getPayload: () => ({ kind: "text", text, mimeType }),
  }
}

export function createDisabledDownloadAction({
  id,
  label = "Download",
  fileName,
  origin = "original",
}: {
  id: string
  label?: string
  fileName: string
  origin?: ViewerDownloadOrigin
}): ViewerDownloadAction {
  return {
    id,
    label,
    fileName,
    origin,
    isDisabled: true,
    getPayload: () => ({ kind: "none" }),
  }
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
